/**
 * Detects user input that is purely a stop order ("STOP", "stop it now",
 * "cancel that please"). Only unambiguous directives match: every word must
 * be a stop verb or a filler word. Messages that merely CONTAIN a stop word
 * ("stop the scan and list the results") still reach the model as steering,
 * where the terminal-abort check and churn guards in the agent loop provide
 * the backstop.
 *
 * Exception: a mixed message whose FINAL sentence is a pure stop order is
 * still a stop order ("...WHAT DID I JUST SAY. STOP IT NOW"). During the
 * 2026-09-23 runaway incident such messages were queued as steering and the
 * run kept going while the user was shouting stop.
 */
export function isStopDirective(text: string): boolean {
	const normalized = text.toLowerCase().replace(/[^a-z0-9\s]/g, " ");
	const words = normalized.split(/\s+/).filter(Boolean);
	if (words.length === 0) return false;

	const stopVerbs = new Set(["stop", "halt", "abort", "cancel", "quit", "cease", "discontinue"]);
	const fillers = new Set([
		"now",
		"it",
		"that",
		"this",
		"please",
		"immediately",
		"everything",
		"all",
		"working",
		"doing",
		"the",
		"a",
		"an",
		"just",
		"off",
		"up",
		"task",
		"run",
		"agent",
		"loop",
	]);

	function pureStopOrder(candidate: string[]): boolean {
		return candidate.some((w) => stopVerbs.has(w)) && candidate.every((w) => stopVerbs.has(w) || fillers.has(w));
	}

	if (pureStopOrder(words)) return true;

	// Final-sentence check: split on sentence terminators and newlines, then
	// apply the same purity rule to the trailing fragment only.
	const sentences = text
		.split(/[.!?\n;]+/)
		.map((sentence) =>
			sentence
				.toLowerCase()
				.replace(/[^a-z0-9\s]/g, " ")
				.trim(),
		)
		.filter((sentence) => sentence.length > 0);
	const last = sentences[sentences.length - 1];
	if (last === undefined) return false;
	return pureStopOrder(last.split(/\s+/).filter(Boolean));
}
